#!/usr/bin/env bash\nset -euo pipefail\n\n# Ensure the GitHub event payload path is provided\nif [[ -z "${GITHUB_EVENT_PATH:-}" ]]; then\n  echo "❌ GITHUB_EVENT_PATH environment variable is not set"\n  exit 1\nfi\n\n# Extract the PR title using a tiny Python snippet (avoids jq dependency)\nPR_TITLE=$(python - <<'PY'\nimport json, sys\nwith open("$GITHUB_EVENT_PATH") as f:\n    data = json.load(f)\nprint(data.get('pull_request', {}).get('title', ''))\nPY\n)\n\n# Use the provided prefix (default is set by the action metadata)\nPREFIX="${INPUT_PREFIX:-🚀}"\n\nif [[ "$PR_TITLE" == "$PREFIX"* ]]; then\n  echo "✅ PR title starts with required prefix '$PREFIX'"\n  exit 0\nelse\n  echo "❌ PR title does not start with required prefix '$PREFIX'"\n  echo "   Found title: '$PR_TITLE'"\n  exit 1\nfi\n
